Validation:
app_lock_type: ∈{NONE,PIN,BIOMETRIC}
pin_input: 4-8 chữ số; bắt buộc khi kiểu=PIN
auto_lock_seconds: ∈{0,30,60,300}

document_type: ∈{CONTRACT,PAYSLIP,BANK_STATEMENT,SHIFT_SCHEDULE,RECEIPT,OTHER}
document_type: bắt buộc
period_month: Định dạng YYYY-MM; bắt buộc khi loại=PAYSLIP

evidence_type: ∈{DOCUMENT,RECON_RESULT,WORK_LOG_RANGE,NOTE,LETTER}
ref_entity_code: ∈{DOCUMENT,PAY_PERIOD,WORK_LOG,LETTER_DRAFT}
evidence_title: 1-120 ký tự
evidence_title: bắt buộc
evidence_tags: Tối đa 10 thẻ, mỗi thẻ ≤ 20 ký tự

corridor_code: Dạng XX-YY (nước gửi - nước làm việc)
corridor_code: bắt buộc
origin_country_code: ∈{VN}
origin_country_code: bắt buộc
destination_country_code: ∈{JP}
destination_country_code: bắt buộc
corridor_status: ∈{ACTIVE,PLANNED}

source_name: 1-200 ký tự
source_name: bắt buộc
publisher: bắt buộc
source_country_code: ∈{JP,VN}
source_country_code: bắt buộc
source_url: URL hợp lệ
source_url: bắt buộc
source_grade: ∈{A,B,C}
source_grade: bắt buộc
source_language: ∈{ja,vi,en}
source_language: bắt buộc
accessed_date: bắt buộc
source_status: ∈{ACTIVE,INACTIVE}

summary_vi: 20-3000 ký tự
summary_vi: bắt buộc
recipient_type: ∈{EMPLOYER,SUPPORT_ORG,AGENCY,OTHER}
recipient_type: bắt buộc
letter_purpose: ∈{ASK_CLARIFICATION,REQUEST_PAYSLIP,REPORT_ISSUE,OTHER}
letter_purpose: bắt buộc

desk_case_status: ∈{NEW,IN_PROGRESS,WAITING_WORKER,CLOSED}
closing_reason: ∈{RESOLVED,REFERRED,WITHDRAWN,NO_RESPONSE}; bắt buộc khi đóng
closing_note: ≤ 2000 ký tự

login_identifier: Email hoặc số điện thoại hợp lệ [CẦN XÁC NHẬN loại định danh]
login_identifier: bắt buộc
account_status: ∈{ACTIVE,LOCKED,PENDING,DELETED}

config_key: Chữ hoa, số, gạch dưới
config_key: bắt buộc
config_group: ∈{LLM_QUOTA,ABSTAIN,OCR,SHARING,SECURITY,OTHER}
config_group: bắt buộc
config_value: Đúng kiểu theo value_type
config_value: bắt buộc
value_type: ∈{INT,DECIMAL,STRING,BOOL}
value_type: bắt buộc
plan_code: ∈{FREE,PRO}
plan_code: bắt buộc
plan_name: bắt buộc
monthly_price_amount: ≥0
price_currency_code: ∈{JPY}
llm_monthly_quota: ≥0
llm_monthly_quota: bắt buộc
plan_status: ∈{ACTIVE,RETIRED}

data_class: ∈{AUDIT_LOG,ACCESS_LOG,SESSION,SYNC_BACKUP,NOTIFICATION,DELETED_ACCOUNT}
data_class: bắt buộc
retention_days: ≥1 [CẦN XÁC NHẬN giá trị]
retention_days: bắt buộc
expiry_action: ∈{DELETE,ANONYMIZE}
